package com.nishu.app.audio

import kotlin.math.abs
import kotlin.math.sign
import kotlin.math.tanh

/**
 * Loudness leveler and soft-knee limiter for on-device speech processing.
 *
 * Implements:
 * 1. Target scalar gain application.
 * 2. Continuous soft-knee polynomial limiter using tanh compression curve:
 *    - Linear response up to [KNEE_THRESHOLD] (0.88).
 *    - Smooth C1-continuous compression above [KNEE_THRESHOLD], strictly capping peaks at [MAX_CEILING] (0.98).
 *    - Eliminates odd-harmonic distortion and harsh spectral splatter generated by hard clipping.
 */
class LoudnessNormalizer(
    private val gain: Float = 1.0f,
    private val kneeThreshold: Float = KNEE_THRESHOLD,
    private val maxCeiling: Float = MAX_CEILING,
) {
    private val headroom = maxCeiling - kneeThreshold

    /**
     * Applies gain and soft-knee limiting to [samples] in place.
     */
    fun process(samples: FloatArray): FloatArray {
        if (gain == 1.0f && kneeThreshold >= maxCeiling) return samples

        for (i in samples.indices) {
            val amplified = samples[i] * gain
            val absVal = abs(amplified)

            samples[i] = if (absVal <= kneeThreshold) {
                amplified
            } else {
                val excess = (absVal - kneeThreshold) / headroom
                val compressed = kneeThreshold + headroom * tanh(excess.toDouble()).toFloat()
                sign(amplified) * compressed
            }
        }
        return samples
    }

    /**
     * Applies soft-knee limiting to a single sample.
     */
    fun limitSample(x: Float): Float {
        val absVal = abs(x)
        if (absVal <= kneeThreshold) return x
        val excess = (absVal - kneeThreshold) / headroom
        val compressed = kneeThreshold + headroom * tanh(excess.toDouble()).toFloat()
        return sign(x) * compressed
    }

    companion object {
        const val KNEE_THRESHOLD = 0.88f
        const val MAX_CEILING = 0.98f

        /**
         * Clamps and applies soft-knee compression in place without scaling gain.
         */
        fun limitInPlace(samples: FloatArray) {
            val normalizer = LoudnessNormalizer(gain = 1.0f)
            normalizer.process(samples)
        }
    }
}
